def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    david_prev = None
    strongest_prev = 0.0
    urgent_opp_count = 0

    for oid, opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                b = float(bid)
                prev_bids.append(b)
                if b > strongest_prev:
                    strongest_prev = b
                if oid == 'David':
                    david_prev = b
            except Exception:
                pass

    if david_prev is None:
        david_prev = strongest_prev if strongest_prev > 0 else DAILY_SALARY * 0.75

    tight_supply = supply <= 18
    abundant_supply = supply >= 22
    danger = hp <= 3 or no_water_days >= 1
    severe_danger = hp <= 2 or no_water_days >= 2

    if severe_danger:
        target = max(DAILY_SALARY * 0.95, david_prev + 2.5)
    elif danger:
        if tight_supply:
            target = max(DAILY_SALARY * 0.88, david_prev + 1.5)
        else:
            target = max(DAILY_SALARY * 0.78, david_prev + 1.0)
    else:
        if abundant_supply and urgent_opp_count == 0:
            target = DAILY_SALARY * 0.34
        elif abundant_supply:
            target = DAILY_SALARY * 0.42
        elif tight_supply:
            target = max(DAILY_SALARY * 0.68, david_prev * 0.82)
        else:
            target = max(DAILY_SALARY * 0.52, david_prev * 0.72)

    if day >= 8 and hp > 4 and no_water_days == 0:
        target *= 0.92

    if budget < target:
        if severe_danger or (danger and tight_supply):
            return float(budget)
        return float(min(budget, max(0.0, DAILY_SALARY * 0.4)))

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = {oid: info for oid, info in opponents_status.items() if info['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for oid, info in alive_opponents.items():
        prev = info.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid on supply pressure
    supply_ratio = (supply - 15) / 10.0  # 0 to 1
    base_bid = DAILY_SALARY * (0.4 + 0.3 * (1 - supply_ratio))  # 0.4-0.7 of salary

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If opponents were very aggressive yesterday, they likely still are
        if highest_prev > 100:
            if hp <= 2:
                # Desperate: bid just above highest_prev
                target = min(budget, highest_prev + 2)
                return max(target, DAILY_SALARY * 0.5)
            elif hp <= 5:
                # Moderate risk: match highest_prev
                target = min(budget, highest_prev)
                return max(target, base_bid)
            else:
                # Healthy: save money, bid conservatively
                return min(budget, base_bid * 0.8)
        else:
            # Moderate competition: slightly undercut if healthy, otherwise outbid
            if hp <= 3:
                target = highest_prev + 1.5
            else:
                target = max(base_bid, highest_prev * 0.9)
            return min(budget, target)
    else:
        # No yesterday info: rely on supply heuristic
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, base_bid)
